// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // fuzzed caller address: the fuzzer will try many addresses to find difference
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address as it's sometimes special
        vm.assume(caller != address(0));

        // Try calling sudicideAnyone as `caller` and record whether it reverts
        bool ok;
        // ensure caller has some ETH so if implementation attempted payable interactions it wouldn't fail due to balance
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the correct contract only the deployer (owner) can succeed.
        // The test asserts that if `caller` is the deployer (address(this) that deployed c in setUp), call must succeed;
        // and if `caller` is not the deployer it must fail. This property holds for the reference and is violated by the mutant.
        if (caller == address(this)) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}
